def collect_root_entries(premises):
    nodes=premises.get('nodes',[])
    roots=premises.get('roots',[])
    byid={}
    for n in nodes:
        byid[n.get('id')]=n
    entries=[]
    for root in roots:
        todo=[root]
        seen=set()
        while todo:
            nid=todo.pop()
            if nid in seen or nid not in byid:
                continue
            seen.add(nid)
