def apply_disposition_update(inputs,premises):
    task=inputs.get('task_id')
    entries=collect_root_entries(premises)
    duties=[]
    retention_permissions=[]
    retention_prohibitions=[]
    for t,r in entries:
        if not isinstance(t,list) or not t:
            continue
        if t[0]=='obligation' and len(t)>=5 and is_disposition_action(t[2]) and has_tag(t[2],'confidential_information'):
            duties.append((t,r))
        if t[0]=='permission' and len(t)>=3 and has_tag(t[2],'retain') and has_tag(t[2],'confidential_information'):
            retention_permissions.append((t,r))
        if t[0]=='prohibition' and len(t)>=3 and has_tag(t[2],'retain') and has_tag(t[2],'confidential_information'):
            retention_prohibitions.append((t,r))
    if task=='nda-16':
        if not duties:
            return {'handled':False,'answer':None,'used_nodes':[]}
        relevant=[]
        for t,r in duties:
            relevant.append(r)
            trigger=t[3]
            if has_tag(trigger,'on_termination') or has_tag(trigger,'on_cessation'):
                return {'handled':True,'answer':'Entailment','used_nodes':[r]}
        request_only=False
        for t,r in duties:
            if has_tag(t[3],'on_request'):
                request_only=True
        if request_only:
            return {'handled':True,'answer':'NotMentioned','used_nodes':unique(relevant)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    if task=='nda-20':
        if retention_permissions:
            used=[]
            for t,r in retention_permissions:
                used.append(r)
            return {'handled':True,'answer':'Entailment','used_nodes':unique(used)}
        if retention_prohibitions:
            used=[]
            for t,r in retention_prohibitions:
                used.append(r)
            return {'handled':True,'answer':'Contradiction','used_nodes':unique(used)}
        exhaustive=[]
        for t,r in duties:
            if has_tag(t[2],'copies_of'):
                exhaustive.append(r)
        if exhaustive:
            return {'handled':True,'answer':'Contradiction','used_nodes':unique(exhaustive)}
        return {'handled':False,'answer':None,'used_nodes':[]}
    return {'handled':False,'answer':None,'used_nodes':[]}

def apply(inputs,premises):
    task=inputs.get('task_id')
    if task in ('nda-5','nda-7'):
        return apply_disclosure_update(inputs,premises)
    if task in ('nda-16','nda-20'):
        return apply_disposition_update(inputs,premises)
    return {'handled':False,'answer':None,'used_nodes':[]}

