def disposition_scope(t):
    base=['confidential_information']
    if any_phrase(t,['document','file','material','tangible item','property comprising','embodiment']):
        base=['materials_containing',['confidential_information']]
    if any_phrase(t,['all copies','copies thereof','and all copies','copy thereof','copies, electronic']):
        return ['information_union',base,['copies_of',base]]
    return base

def disposition_trigger(t):
    xs=[]
    if any_phrase(t,['upon termination','on termination','after termination','upon expiration','on expiration','termination of service','relationship ends']):
        xs.append(['on_termination','source-stated termination or expiration'])
    if any_phrase(t,['completion of the purpose','completion of purpose','purpose is completed','cessation of the purpose','end of service']):
        xs.append(['on_cessation','source-stated completion or cessation'])
    if any_phrase(t,['upon request','written request','receipt of a written request','at the request']):
        xs.append(['on_request','source-stated request'])
    if not xs:
        return None
    v=xs[0]
    i=1
    while i<len(xs):
        v=['alternative_trigger',v,xs[i]]
        i+=1
    return v

def retention_permission(t,actor):
    modal=any_phrase(t,['may retain','may maintain a single copy','may maintain one copy','may keep a copy','entitled to retain'])
    if not modal:
        return None
    scope=['confidential_information']
    if 'backup' in t:
        scope=['backup_copy_of',['confidential_information']]
    elif 'single copy' in t or 'one copy' in t:
        scope=['single_copy_of',['confidential_information']]
    elif 'record copy' in t or 'archival' in t or 'archive' in t:
        scope=['record_copy_of',['confidential_information']]
    cond=['after_disposition','return or destruction requirement']
    restriction=None
    if any_phrase(t,['required by law','applicable law','regulatory compliance','legal department','legal counsel','compliance with the terms']):
        restriction=['retention_restriction','legal or regulatory compliance']
    elif any_phrase(t,['archival purpose','archive purpose']):
        restriction=['retention_restriction','archival purpose']
    if restriction is not None:
        cond=['and_condition',cond,restriction]
    return ['permission',actor,['retain',scope],cond]

